<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require_admin();$error='';$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');try{if($action==='create_user'){$username=trim((string)($_POST['username']??''));$full=trim((string)($_POST['full_name']??''));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'user');if(!preg_match('/^[A-Za-z0-9._-]{3,80}$/',$username))throw new RuntimeException('Username must be 3–80 characters and use letters, numbers, dots, underscores, or hyphens.');if($full==='')throw new RuntimeException('Full name is required.');if(!in_array($role,['admin','user'],true))$role='user';$s=db()->prepare('INSERT INTO dbo.users(username,password_hash,full_name,role,is_active) OUTPUT INSERTED.id VALUES(?,?,?,?,1)');$s->execute([$username,password_hash($password,PASSWORD_DEFAULT),$full,$role]);$id=(int)$s->fetchColumn();audit_log('CREATE','user',$id,'Created user '.$username,null,['username'=>$username,'full_name'=>$full,'role'=>$role,'is_active'=>1]);$notice='User created successfully.';}elseif($action==='toggle_user'){$id=(int)($_POST['id']??0);if($id===(int)current_user()['id'])throw new RuntimeException('You cannot deactivate your own account.');$s=db()->prepare('SELECT id,username,full_name,role,is_active FROM dbo.users WHERE id=?');$s->execute([$id]);$before=$s->fetch();if(!$before)throw new RuntimeException('User not found.');$new=(int)!((int)$before['is_active']);db()->prepare('UPDATE dbo.users SET is_active=?,updated_at=SYSDATETIME() WHERE id=?')->execute([$new,$id]);$after=$before;$after['is_active']=$new;audit_log($new?'ACTIVATE':'DEACTIVATE','user',$id,($new?'Activated':'Deactivated').' user '.$before['username'],$before,$after);$notice='User status updated.';}}catch(Throwable $e){$error=$e instanceof PDOException && str_contains(strtolower($e->getMessage()),'duplicate')?'That username already exists.':$e->getMessage();}}
$users=db()->query('SELECT id,username,full_name,role,is_active,created_at FROM dbo.users ORDER BY id')->fetchAll();?><?php $pageTitle='User Management'; $activePage='users'; require __DIR__.'/includes/header.php'; ?><section class="content"><div class="page-intro"><div><h2>Manage users</h2><p>Create accounts and deactivate access. Account changes are written to the audit history.</p></div></div><?php if($notice):?><div class="notice notice-success"><strong>Success</strong><span><?=h($notice)?></span></div><?php endif;?><?php if($error):?><div class="notice notice-error"><strong>Could not complete action</strong><span><?=h($error)?></span></div><?php endif;?><section class="panel"><div class="panel-head"><div><h3>Create user</h3><p>Passwords are stored as secure hashes.</p></div></div><form method="post" class="user-create-form"><?=csrf_field()?><input type="hidden" name="action" value="create_user"><label class="field"><span>Full name</span><input name="full_name" required></label><label class="field"><span>Username</span><input name="username" minlength="3" maxlength="80" required></label><label class="field"><span>Temporary password</span><input type="password" name="password" required></label><label class="field"><span>Role</span><select name="role"><option value="user">User</option><option value="admin">Administrator</option></select></label><button class="btn btn-primary" type="submit">Create account</button></form></section><section class="panel data-panel"><div class="panel-head"><div><h3>Existing accounts</h3><p><?=count($users)?> user account(s)</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>ID</th><th>Full name</th><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=h($u['id'])?></td><td><?=h($u['full_name'])?></td><td><?=h($u['username'])?></td><td><?=h(ucfirst($u['role']))?></td><td><span class="action-pill <?=$u['is_active']?'action-activate':'action-deactivate'?>"><?=$u['is_active']?'Active':'Inactive'?></span></td><td><?=h($u['created_at'])?></td><td><?php if((int)$u['id']!==(int)current_user()['id']):?><form method="post" onsubmit="return confirm('Change this user account status?')"><?=csrf_field()?><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id" value="<?=h($u['id'])?>"><button class="btn btn-secondary btn-small" type="submit"><?=$u['is_active']?'Deactivate':'Activate'?></button></form><?php else:?><span class="muted">Current account</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></section><?php require __DIR__.'/includes/footer.php'; ?>
